html:
{%- import 'afintrix_theme/templates/print/afintrix_print.html' as afx -%}
<div class="afx-print">
	{{ afx.head(_('Payslip'), doc.name, [
		(_('Period'), '%s - %s' % (frappe.utils.formatdate(doc.start_date), frappe.utils.formatdate(doc.end_date))),
		(_('Paid days'), doc.payment_days),
	]) }}

	{{ afx.parties([
		(_('Employee'), doc.employee_name, '%s · %s' % (doc.employee, doc.designation or '')),
		(_('Company'), doc.company, doc.department or ''),
	]) }}

	{{ afx.table_open([
		(_('Earnings'), '58%', 'left'),
		(_('Amount'), '38%', 'right'),
	]) }}
	{%- for row in doc.earnings %}
	<tr>
		<td>{{ loop.index }}</td>
		<td>{{ row.salary_component }}</td>
		<td class="text-right">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
	</tr>
	{%- endfor %}
	{{ afx.table_close() }}

	{%- if doc.deductions %}
	{{ afx.table_open([
		(_('Deductions'), '58%', 'left'),
		(_('Amount'), '38%', 'right'),
	]) }}
	{%- for row in doc.deductions %}
	<tr>
		<td>{{ loop.index }}</td>
		<td>{{ row.salary_component }}</td>
		<td class="text-right">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
	</tr>
	{%- endfor %}
	{{ afx.table_close() }}
	{%- endif %}

	{{ afx.summary([
		(_('Gross pay'), frappe.utils.fmt_money(doc.gross_pay, currency=doc.currency), False),
		(_('Total deductions'), frappe.utils.fmt_money(doc.total_deduction, currency=doc.currency), False),
		(_('Net pay'), frappe.utils.fmt_money(doc.net_pay, currency=doc.currency), True),
	]) }}

	{{ afx.terms(_('In words'), doc.total_in_words) }}
</div>
